SET SESSION sql_mode='STRICT_ALL_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION,NO_ZERO_DATE,NO_ZERO_IN_DATE';
DELIMITER //
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_invitation_claim_next_v1(OUT p_disposition VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,OUT p_outbox_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,OUT p_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,OUT p_invitation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,OUT p_payload MEDIUMBLOB) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_outbox CHAR(36); DECLARE v_invitation CHAR(36); DECLARE v_state VARCHAR(16); DECLARE v_status VARCHAR(16); DECLARE v_expires DATETIME(6); DECLARE v_payload MEDIUMBLOB; DECLARE v_attempt CHAR(36); DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office delivery transaction denied'; END IF; SET p_disposition='EMPTY',p_outbox_id=NULL,p_attempt_id=NULL,p_invitation_id=NULL,p_payload=NULL; SET TRANSACTION ISOLATION LEVEL READ COMMITTED; START TRANSACTION; SELECT outbox_id,invitation_id INTO v_outbox,v_invitation FROM office_invitation_outbox FORCE INDEX(idx_office_invitation_outbox_claim) WHERE state='QUEUED' ORDER BY created_at,outbox_id LIMIT 1; IF v_outbox IS NULL THEN COMMIT; LEAVE proc; END IF; SELECT status,expires_at INTO v_status,v_expires FROM office_invitation WHERE invitation_id=v_invitation FOR UPDATE; SELECT state,payload_ciphertext INTO v_state,v_payload FROM office_invitation_outbox WHERE outbox_id=v_outbox FOR UPDATE; IF v_state<>'QUEUED' THEN COMMIT; SET p_disposition='RETRY'; LEAVE proc; END IF; IF v_status<>'ISSUED' THEN ROLLBACK; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office queued lifecycle denied'; END IF; IF v_expires<=UTC_TIMESTAMP(6) THEN COMMIT; SET p_disposition='DUE'; LEAVE proc; END IF; SET v_attempt=LOWER(UUID()); UPDATE office_invitation_outbox SET state='CLAIMED',attempt_id=v_attempt,attempt_count=1,claimed_at=UTC_TIMESTAMP(6),updated_at=IF(UTC_TIMESTAMP(6)>updated_at,UTC_TIMESTAMP(6),DATE_ADD(updated_at,INTERVAL 1 MICROSECOND)) WHERE outbox_id=v_outbox AND state='QUEUED'; IF ROW_COUNT()<>1 THEN ROLLBACK; SET p_disposition='RETRY'; LEAVE proc; END IF; COMMIT; SET p_disposition='CLAIMED',p_outbox_id=v_outbox,p_attempt_id=v_attempt,p_invitation_id=v_invitation,p_payload=v_payload; END//
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_invitation_expire_due_v1(IN p_limit SMALLINT UNSIGNED,OUT p_expired SMALLINT UNSIGNED) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_invitation CHAR(36); DECLARE v_version BIGINT; DECLARE v_correlation BINARY(16); DECLARE v_issued BIGINT UNSIGNED; DECLARE v_done BOOL DEFAULT FALSE; DECLARE due_cursor CURSOR FOR SELECT invitation_id FROM office_invitation FORCE INDEX(idx_office_invitation_status_expiry) WHERE status='ISSUED' AND expires_at<=UTC_TIMESTAMP(6) ORDER BY expires_at,invitation_id LIMIT p_limit; DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 OR p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office expiry input denied'; END IF; SET p_expired=0; SET TRANSACTION ISOLATION LEVEL READ COMMITTED; OPEN due_cursor; expiry_loop: LOOP FETCH due_cursor INTO v_invitation; IF v_done THEN LEAVE expiry_loop; END IF; START TRANSACTION; SET v_version=NULL; SET v_issued=NULL; SELECT i.version,s.correlation_id INTO v_version,v_correlation FROM office_invitation i JOIN office_invitation_issuance s ON s.issuance_id=i.issuance_id WHERE i.invitation_id=v_invitation AND i.status='ISSUED' AND i.expires_at<=UTC_TIMESTAMP(6) FOR UPDATE; IF v_version IS NOT NULL THEN SELECT event_id INTO v_issued FROM office_invitation_event WHERE invitation_id=v_invitation AND event_kind='ISSUED' FOR UPDATE; IF v_issued IS NULL THEN ROLLBACK; CLOSE due_cursor; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office expiry evidence denied'; END IF; INSERT INTO office_invitation_event(invitation_id,event_kind,causation_event_id,actor_user_id,bearer_token_hash,observed_outbox_state,correlation_id,occurred_at) VALUES(v_invitation,'EXPIRED',v_issued,NULL,NULL,NULL,v_correlation,UTC_TIMESTAMP(6)); UPDATE office_invitation SET status='EXPIRED',version=version+1 WHERE invitation_id=v_invitation AND status='ISSUED' AND version=v_version; IF ROW_COUNT()<>1 THEN ROLLBACK; CLOSE due_cursor; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office expiry race'; END IF; SET p_expired=p_expired+1; END IF; COMMIT; END LOOP; CLOSE due_cursor; END//
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_invitation_settle_delivery_v1(IN p_outbox_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,IN p_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,IN p_result VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,IN p_message_id VARCHAR(320) CHARACTER SET ascii COLLATE ascii_bin,OUT p_disposition VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_invitation CHAR(36); DECLARE v_state VARCHAR(16); DECLARE v_attempt CHAR(36); DECLARE v_cancel BOOL; DECLARE v_issued BIGINT UNSIGNED; DECLARE v_correlation BINARY(16); DECLARE v_evidence BOOL; DECLARE v_code VARCHAR(64); DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 OR p_outbox_id NOT REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR p_attempt_id NOT REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office settle identity denied'; END IF; IF p_result='SMTP_ACCEPTED' THEN IF p_message_id IS NULL OR p_message_id='' OR CHAR_LENGTH(p_message_id)>320 OR p_message_id NOT REGEXP '^[ -~]+$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office accepted receipt denied'; END IF; ELSEIF p_result IN ('SMTP_UNKNOWN','SMTP_STALE') THEN IF p_message_id IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office unknown receipt denied'; END IF; ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office settle result denied'; END IF; SET p_disposition='FENCED'; SET TRANSACTION ISOLATION LEVEL READ COMMITTED; START TRANSACTION; SELECT invitation_id INTO v_invitation FROM office_invitation_outbox WHERE outbox_id=p_outbox_id; IF v_invitation IS NULL THEN COMMIT; LEAVE proc; END IF; SELECT invitation_id FROM office_invitation WHERE invitation_id=v_invitation FOR UPDATE; SELECT state,attempt_id,cancel_requested,result_code INTO v_state,v_attempt,v_cancel,v_code FROM office_invitation_outbox WHERE outbox_id=p_outbox_id FOR UPDATE; IF v_attempt<>p_attempt_id OR v_cancel THEN COMMIT; LEAVE proc; END IF; IF v_state='UNKNOWN' AND p_result='SMTP_ACCEPTED' AND v_code='SMTP_STALE' THEN SELECT EXISTS(SELECT 1 FROM office_invitation_event WHERE invitation_id=v_invitation AND event_kind='DELIVERY_OBSERVED') INTO v_evidence; IF v_evidence THEN COMMIT; LEAVE proc; END IF; ELSEIF v_state<>'CLAIMED' THEN IF (v_state='SMTP_ACCEPTED' AND p_result='SMTP_ACCEPTED') OR (v_state='UNKNOWN' AND p_result='SMTP_UNKNOWN' AND v_code='SMTP_UNKNOWN') THEN SET p_disposition='REPLAYED'; END IF; COMMIT; LEAVE proc; END IF; UPDATE office_invitation_outbox SET state=IF(p_result='SMTP_ACCEPTED','SMTP_ACCEPTED','UNKNOWN'),payload_ciphertext=NULL,message_id=IF(p_result='SMTP_ACCEPTED',p_message_id,NULL),result_code=p_result,finished_at=UTC_TIMESTAMP(6),updated_at=IF(UTC_TIMESTAMP(6)>updated_at,UTC_TIMESTAMP(6),DATE_ADD(updated_at,INTERVAL 1 MICROSECOND)) WHERE outbox_id=p_outbox_id; IF p_result<>'SMTP_STALE' THEN SELECT e.event_id,s.correlation_id INTO v_issued,v_correlation FROM office_invitation_event e JOIN office_invitation i ON i.invitation_id=e.invitation_id JOIN office_invitation_issuance s ON s.issuance_id=i.issuance_id WHERE e.invitation_id=v_invitation AND e.event_kind='ISSUED' FOR UPDATE; INSERT INTO office_invitation_event(invitation_id,event_kind,causation_event_id,actor_user_id,bearer_token_hash,observed_outbox_state,correlation_id,occurred_at) VALUES(v_invitation,'DELIVERY_OBSERVED',v_issued,NULL,NULL,IF(p_result='SMTP_ACCEPTED','SMTP_ACCEPTED','UNKNOWN'),v_correlation,UTC_TIMESTAMP(6)); END IF; COMMIT; SET p_disposition='APPLIED'; END//
DELIMITER ;
